import { MONSTER_DATA, MONSTER_ZONES } from "@hunt/hunt-data/monarch";
import { getLocalSolvedPuzzleMap } from "@hunt/puzzle-components";

export type PuzzmonInfo = {
  slug: string;
  altText: string;
  assetA: string;
  assetB: string;
};

const theBrightsPuzzmon = MONSTER_DATA[MONSTER_ZONES.THE_BRIGHTS];
const BRIGHTS_ORDER = [
  "comettails",
  "lanternbot",
  "incandabra",
  "prismoidia",
  "mistermoon",
  "glimmerpom",
  "twinkleish",
  "knightbulb",
  "bumblebeam",
  "wattissimo",
];

export const ALL_PUZZMON_INFO: PuzzmonInfo[] = [
  ...BRIGHTS_ORDER.map((slug) => {
    const data = theBrightsPuzzmon[slug];
    if (!data) {
      throw new Error(`Missing puzzmon data for slug ${slug}`);
    }
    return {
      slug,
      assetA: data.imageSrc,
      assetB: data.imageSrc2 ?? data.imageSrc,
      altText: data.altText,
    };
  }),
];

export const getPuzzmonInfo = (
  showAllPuzzmon: boolean,
): (PuzzmonInfo | null)[] => {
  if (showAllPuzzmon) {
    return ALL_PUZZMON_INFO;
  }
  const localSolvedPuzzleMap = getLocalSolvedPuzzleMap();
  return ALL_PUZZMON_INFO.map((info) =>
    Object.values(localSolvedPuzzleMap).find(
      ({ puzzmonSlug }) => puzzmonSlug === info.slug,
    )
      ? info
      : null,
  );
};
