type AkariGridProps = {
  grid: AkariCell[][];
  colors: string[][];
};

export const AkariGrid = ({ grid, colors }: AkariGridProps) => {
  return (
    <table className="akari-grid border-collapse">
      <tbody>
        {grid.map((row, rowIdx) => (
          <tr key={rowIdx}>
            {row.map((cell, colIdx) => {
              // Determine if this cell is on the outer border
              const isTop = rowIdx === 0;
              const isBottom = rowIdx === grid.length - 1;
              const isLeft = colIdx === 0;
              const isRight = colIdx === row.length - 1;

              // Compose border classes
              let borderClass = "border border-black";
              if (isTop) borderClass += " border-t-4";
              if (isBottom) borderClass += " border-b-4";
              if (isLeft) borderClass += " border-l-4";
              if (isRight) borderClass += " border-r-4";

              let cellClass = colors[rowIdx][colIdx];
              if (cellClass === "bg-black") {
                cellClass += " text-white";
              }
              const cellText = cell;

              return (
                <td
                  key={colIdx}
                  className={`${cellClass} w-10 h-10 text-center align-middle ${borderClass}`}
                >
                  {cellText}
                </td>
              );
            })}
          </tr>
        ))}
      </tbody>
    </table>
  );
};

const getIsDark = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-color-scheme: dark)").matches;

type GridChoice = {
  isDark: boolean;
  light: AkariCell[][];
  dark: AkariCell[][];
  lightColors: string[][];
  darkColors: string[][];
};

const RenderAkariGrid = ({
  isDark,
  light,
  dark,
  lightColors,
  darkColors,
}: GridChoice) => {
  return (
    <AkariGrid
      grid={isDark ? dark : light}
      colors={isDark ? darkColors : lightColors}
    />
  );
};

export const PuzzleComponent = () => {
  // Track dark mode and update on system preference change
  const [isDark, setIsDark] = React.useState(getIsDark());
  const [showAllPuzzmon, setShowAllPuzzmon] = useState(false);

  const puzzmonInfo = getPuzzmonInfo(showAllPuzzmon);

  React.useEffect(() => {
    const mql = window.matchMedia("(prefers-color-scheme: dark)");
    const handleChange = (e: MediaQueryListEvent) => {
      setIsDark(e.matches);
    };

    mql.addEventListener("change", handleChange);

    setIsDark(mql.matches);

    return () => {
      mql.removeEventListener("change", handleChange);
    };
  }, []);

  const puzzleGrid = getPuzzleGrid(puzzmonInfo, isDark);
  const flavorText = isDark ? "It's too dark." : "It's too light.";
  return (
    <>
      {(showAllPuzzmon || puzzmonInfo.some((puzzmon) => puzzmon === null)) && (
        <ShowAllPuzzmonInfoBox
          showAllPuzzmon={showAllPuzzmon}
          onToggle={() => {
            setShowAllPuzzmon(!showAllPuzzmon);
          }}
        />
      )}
      <FlavorText>{flavorText}</FlavorText>
      {isDark ? (
        <div className="mx-auto flex flex-col items-start gap-1">
          <span className="text-2xl font-bold pl-2">⬇️</span>
          <AkariGrid grid={puzzleGrid} colors={PUZZLE_COLORS} />
        </div>
      ) : (
        <div className="mx-auto flex flex-row items-start gap-1">
          <span className="text-2xl font-bold pt-2">➡️</span>
          <AkariGrid grid={puzzleGrid} colors={PUZZLE_COLORS} />
        </div>
      )}
      <span className="mt-10 mb-4 text-center text-2xl font-bold">
        Example:
      </span>
      <div className="grid grid-cols-2 gap-4">
        <div className="mx-auto">
          <RenderAkariGrid
            isDark={isDark}
            light={LIGHTS_UP_EXAMPLE_GRID}
            dark={LIGHTS_DOWN_EXAMPLE_GRID}
            lightColors={LIGHTS_UP_EXAMPLE_COLORS}
            darkColors={LIGHTS_DOWN_EXAMPLE_COLORS}
          />
        </div>
        <div className="mx-auto">
          <RenderAkariGrid
            isDark={isDark}
            light={LIGHTS_UP_EXAMPLE_GRID_SOLVED}
            dark={LIGHTS_DOWN_EXAMPLE_GRID_SOLVED}
            lightColors={LIGHTS_UP_EXAMPLE_SOLVED_COLORS}
            darkColors={LIGHTS_DOWN_EXAMPLE_SOLVED_COLORS}
          />
        </div>
      </div>
    </>
  );
};
